<template><el-card><template #header>租户管理</template><el-table :data="rows" v-loading="loading"><el-table-column prop="tenantNo" label="租户号"/><el-table-column prop="name" label="租户名称"/><el-table-column label="状态"><template #default="s">{{statusLabel(s.row.status)}}</template></el-table-column><el-table-column prop="expireAt" label="到期时间"/><el-table-column label="操作"><template #default="s"><el-button link :loading="toggling===s.row.id" @click="toggle(s.row)">{{s.row.status==='DISABLED'?'启用':'停用'}}</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!rows.length" description="暂无租户"/></el-card></template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import {ElMessage} from 'element-plus';import {merchantApi} from '@/api';const rows=ref<any[]>([]),loading=ref(false),toggling=ref<number>();const labels:any={NORMAL:'正常',TRIAL:'试用中',EXPIRED:'已到期',DISABLED:'已禁用',ENABLED:'启用'};const statusLabel=(s:string)=>labels[s]||'未知状态';async function load(){loading.value=true;try{const r:any=await merchantApi.list({page:1,size:50});const d=r?.data||r;rows.value=d?.list||d?.items||[]}catch(e:any){ElMessage.error(e?.message||'租户加载失败')}finally{loading.value=false}}async function toggle(r:any){if(toggling.value===r.id)return;toggling.value=r.id;try{if(r.status==='DISABLED')await merchantApi.enable(r.id);else await merchantApi.disable(r.id);ElMessage.success('操作成功');await load()}catch(e:any){ElMessage.error(e?.response?.data?.message||e?.message||'操作失败')}finally{toggling.value=undefined}}onMounted(load);</script>
